import {createFishKit} from './fish-state.js';
import {CURRENT_SAVE_VERSION} from './config.js';
/** Fish uses the same revision/clone/commit boundary as every prior area. @param {import('./engine.js').State} state @param {import('./engine.js').Command} command @param {import('./engine.js').DomainEvent[]} events @returns {string|undefined} */
export function applyFishCommand(state,command,events){if(state.saveVersion!==CURRENT_SAVE_VERSION)return 'fishMigrationRequired';const g=state.fish;if(command.type==='enterFishPond'){if(g?.visited)return 'fishAlreadyEntered';state.fish=createFishKit(state.tick);events.push({type:'fishEntered'});return;}if(!g?.visited)return 'fishNotVisited';const pond=g.ponds.find(p=>p.id===command.fishPond);if(!pond)return 'fishPondMissing';if(command.type==='fish.inspect'){g.stats.inspections++;events.push({type:'fishInspected'});return;}return 'invalidFishCommand';}
